\begin{tikzpicture}[x=18mm,y=18mm,draw=black,text=black,line width=0.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\pgfmathsetmacro{\coneHeight}{2.15}
\pgfmathsetmacro{\baseDepth}{0.2}
\pgfmathsetmacro{\tangentAngle}{asin(\baseDepth/\coneHeight)}
