\pgfmathsetmacro{\tangentY}{\baseDepth*sin(\tangentAngle)}
\coordinate (A) at (0,\coneHeight);
\coordinate (O) at (0,0);
\coordinate (R) at (1,0);
\coordinate (TL) at (-\tangentX,\tangentY);
\coordinate (TR) at (\tangentX,\tangentY);
\draw (TL)--(A)--(TR);
\draw (TL) arc[start angle={180-\tangentAngle},end angle={360+\tangentAngle},x radius=1,y radius=\baseDepth];
\draw[dashed] (TR) arc[start angle=\tangentAngle,end angle={180-\tangentAngle},x radius=1,y radius=\baseDepth];
\draw[dashed,line width=0.4pt] (A)--(O) node[midway,right] {$h$};
\draw[dashed,line width=0.4pt] (O)--(R) node[midway,above] {$r$};
\draw[line width=0.4pt] ($(O)!2mm!(A)$)--($(O)!2mm!(A)+(2mm,0)$)--($(O)+(2mm,0)$);
\end{tikzpicture}
